/*
 * Lessons (AI tutorial builder). One short lesson per subtopic, made of blocks:
 *   h2 · explain (text) · example (runnable code + output) · predict (code + question + answer)
 *   · mistake (the common mistake, text) · check (multiple-choice question from the bank)
 * The professor edits the first 5–6 lessons by hand; the generator learns her style from those
 * "example lessons" and writes the rest, which she spot-checks.
 * Needs assets/data-lessons-content.js (LESSON_SEEDS: computed outputs per subtopic).
 * TODO(real): lessons are generated by the backend from the book section and the subtopic's
 * misconceptions; style rules are learned from the diff between AI drafts and her edits.
 */
(function () {
  const M = window.MOCK;
  const SEEDS = window.LESSON_SEEDS || {};
  const py = M.course("python");
  const subs = py.taxonomy.flatMap((t) => t.subtopics.map((s) => ({ ...s, topic: t.name, topic_id: t.id })));

  // The most common mistake per subtopic (from Insights where there is one).
  // TODO(real): taken from the subtopic's misconception tags and Insights.
  const MISTAKE = {
    "Aliasing": "Thinking b = a makes a copy. It doesn't: both names point at the same list. Copy with a[:] or list(a).",
    "range() and counted loops": "Expecting the stop value to be included. range(2, 8) stops at 7.",
    "Return values": "Expecting the last expression to come back without return. Without return, the function gives back None.",
    "Keys and values": "Using a list as a key. Lists can change, so Python refuses them; use a tuple.",
    "Slicing": "Counting the stop index as included. 'python'[1:4] is 'yth', three characters.",
    "while loops": "Forgetting to change the loop variable, so the loop never ends.",
    "Scope": "Expecting an assignment inside a function to change the outside name.",
    "Integers and floats": "Expecting 10 / 5 to be 2. It's 2.0: / always gives a float.",
    "Type conversion": "Adding '19' + 1. input() gives a string; convert with int() first.",
    "Assignment": "Reading = as 'equals'. It means 'store this value under that name'.",
    "Operator precedence": "Working left to right: 2 + 3 * 4 is 14, not 20.",
    "if / elif / else": "Expecting several branches to run. Only the first true one does.",
    "Comparison operators": "Writing = when you mean ==.",
    "Logical operators": "Reading 'not a or b' as 'not (a or b)'. not binds tighter.",
    "break and continue": "Mixing them up: break leaves the loop, continue only skips this round.",
    "Loop accumulators": "Setting total = 0 inside the loop, so it resets every round.",
    "Defining functions": "Expecting def to run the body. It only runs when you call it.",
    "String methods": "Calling s.upper() and expecting s to change. Strings can't change; keep the result.",
    "List methods": "Writing xs = xs.append(4). append returns None, so xs becomes None.",
    "Iterating a dict": "Expecting a loop over a dict to give values. It gives keys; use .items().",
    "Counting with dicts": "Writing counts[w] += 1 before the key exists, which raises KeyError.",
    "Immutability": "Trying t[0] = 5 on a tuple. Make a new tuple instead.",
    "try / except": "Catching every error with a bare except, which hides real bugs.",
    "with statements": "Forgetting to close a file opened without with.",
  };

  const code = (s) => s;
  const node = (type, extra, text = "") => ({ type, ...extra, children: [{ text }] });
  const bankCheck = (subName) => {
    const q = M.questions.find((x) => x.course === "python" && x.subtopic === subName && x.type === "multiple_choice" && x.status === "approved");
    return q ? node("check", { question: q.prompt, options: q.options, answer: q.answer, question_id: q.id }) : null;
  };
  const bookSection = (s) => (M.questions.find((q) => q.subtopic_id === s.id)?.source.section) || "Think Python, 3rd ed.";

  // A lesson in the professor's style (what her example lessons taught the generator).
  M.styledLesson = (s) => {
    const seed = SEEDS[s.name];
    if (!seed) return [node("h2", {}, s.name)];
    return [
      node("h2", {}, s.name),
      node("predict", { code: seed.predict, question: seed.predict_q, answer: seed.predict_ans }),
      node("explain", {}, seed.idea),
      node("example", { code: seed.example, output: seed.example_out, source: bookSection(s) }),
      ...(MISTAKE[s.name] ? [node("mistake", {}, MISTAKE[s.name])] : []),
      ...[bankCheck(s.name)].filter(Boolean),
    ];
  };
  // The generator's raw first draft, before it learned her style: long explanation first,
  // textbook-style names, no predict question, no common mistake.
  M.rawDraft = (s) => {
    const seed = SEEDS[s.name] || { idea: "", example: "", example_out: "" };
    return [
      node("h2", {}, s.name),
      node("explain", {}, `In this lesson we will look at ${s.name.toLowerCase()}, an important concept in Python programming that you will use frequently. ${seed.idea} It is worth taking the time to understand this carefully, because many later topics build on it and small misunderstandings here can lead to confusing bugs.`),
      node("explain", {}, "Let us look at an example to see how this works in practice. Read the code carefully and think about what each line does before looking at the output below."),
      // Textbook-style names in the raw draft; output computed for this code (s = 'abcdefgh').
      s.name === "Slicing"
        ? node("example", { code: "s = 'abcdefgh'\nprint(s[1:4])\nprint(s[:2])\nprint(s[-3:])", output: "bcd\nab\nfgh", source: bookSection(s) })
        : node("example", { code: seed.example, output: seed.example_out, source: bookSection(s) }),
      ...[bankCheck(s.name)].filter(Boolean),
    ];
  };

  // ---- Her four example lessons, edited by hand -------------------------------------------
  const sub = (name) => subs.find((x) => x.name === name);
  const exemplarDates = { "Aliasing": "2026-09-14", "range() and counted loops": "2026-09-15", "Return values": "2026-09-21", "Keys and values": "2026-09-27" };
  const exemplarEdits = {
    "Aliasing": { words_before: 131, words_after: 54, changed: 6 },
    "range() and counted loops": { words_before: 118, words_after: 41, changed: 5 },
    "Return values": { words_before: 104, words_after: 48, changed: 5 },
    "Keys and values": { words_before: 126, words_after: 52, changed: 4 },
  };
  // Small hand touches that differ from the generic styled lesson (her voice).
  const handTouch = {
    "Aliasing": (b) => { b[2].children[0].text = "b = a gives your list a second name; there is still only one list. Change it through either name and both see it."; b[3].code = "groceries = ['eggs', 'milk']\nshared = groceries\nshared.append('bread')\nprint(groceries)"; b[3].output = "['eggs', 'milk', 'bread']"; return b; },
    "range() and counted loops": (b) => { b[2].children[0].text = "range(start, stop, step) counts from start and stops before stop. Think of stop as a fence you don't cross."; return b; },
    "Return values": (b) => { b[3].code = "def with_tax(price):\n    return price * 1.1\n\ntotal = with_tax(20)\nprint(round(total, 2))"; b[3].output = "22.0"; return b; },
    "Keys and values": (b) => { b[3].code = "phone_book = {'ana': '555-0101'}\nphone_book['bo'] = '555-0199'\nprint(phone_book['bo'], len(phone_book))"; b[3].output = "555-0199 2"; return b; },
  };

  M.lessons = subs.map((s) => {
    const ex = exemplarDates[s.name];
    if (ex) return { id: `L${s.id}`, sub_id: s.id, sub: s.name, topic: s.topic, topic_id: s.topic_id, status: "example", edited: ex, edits: exemplarEdits[s.name],
      blocks: handTouch[s.name](M.styledLesson(s)) };
    if (s.name === "Slicing") return { id: `L${s.id}`, sub_id: s.id, sub: s.name, topic: s.topic, topic_id: s.topic_id, status: "draft", edited: null, blocks: M.rawDraft(s) };
    return { id: `L${s.id}`, sub_id: s.id, sub: s.name, topic: s.topic, topic_id: s.topic_id, status: "none", edited: null, blocks: null };
  });
  M.lessonMistake = MISTAKE;
  M.lessonBankCheck = bankCheck;
  M.lessonSub = (subId) => subs.find((x) => String(x.id) === String(subId));
  M.lesson = (subId) => M.lessons.find((l) => String(l.sub_id) === String(subId));
  M.lessonTarget = { min: 5, ideal: 6 };

  // ---- What the generator learned from her edits ------------------------------------------
  // TODO(real): rules distilled from the diff between each AI draft and her edited lesson.
  M.lessonStyle = [
    { id: "s1", rule: "Open with a predict-the-output question before any explanation", seen: 4, of: 4, on: true },
    { id: "s2", rule: "Keep each explanation to two or three short sentences", seen: 4, of: 4, on: true, detail: "Your edits cut explanations from about 120 words to about 50." },
    { id: "s3", rule: "Use everyday names in examples (groceries, prices, phone book), not s or foo", seen: 3, of: 4, on: true },
    { id: "s4", rule: "End with the most common mistake for the subtopic, worded as the student would think it", seen: 4, of: 4, on: true },
    { id: "s5", rule: "Finish with one check question from the approved bank", seen: 3, of: 4, on: true },
    { id: "s6", rule: "Name the book section under the worked example", seen: 2, of: 4, on: false, detail: "Seen in only 2 of 4 lessons, so not applied yet." },
  ];
  M.blockLabel = { h2: "Title", explain: "Explanation", example: "Worked example", predict: "Predict the output", mistake: "Common mistake", check: "Check question" };
})();
